    12	/// Opens the fixture profile under `app_data_dir`: the synthetic core on its
    13	/// own files. A legacy `mail.db` in the same directory is never opened here;
    14	/// retiring it is the explicit, disclosed transition (`fixture_transition`).
    15	/// The profile lock and `local-drafts` live in the same directory, so a second
    16	/// writer is rejected.
    17	pub(crate) fn open_fixture_core(
    18	    app_data_dir: &std::path::Path,
    19	) -> Result<(GmailCore, std::path::PathBuf), Box<dyn std::error::Error>> {
    20	    let profile_dir = app_data_dir.join("fixture-profile");
    21	    let core = GmailCore::open_synthetic_profile(
    22	        &profile_dir,
    23	        mail_core::synthetic::WriteControls::from_env(),
    24	        Arc::new(mail_core::clock::SystemClock),
    25	    )?;
    26	    Ok((core, profile_dir))
    27	}
