   134	/// In-memory secret store for synthetic tests only. It is deliberately
   135	/// exported so `crates/mail-core/tests/` can inject it, but production code
   136	/// must never select it as a fallback for [`KeychainSecrets`].
   137	#[derive(Clone, Default)]
   138	pub struct MemorySecrets {
   139	    inner: std::sync::Arc<std::sync::Mutex<MemoryState>>,
   140	}
   141	
   142	#[derive(Default)]
   143	struct MemoryState {
   144	    bundle: Option<String>,
   145	    /// Test control: when set, every operation fails closed.
   146	    unavailable: bool,
   147	}
   148	
   149	impl MemorySecrets {
   150	    pub fn new() -> Self {
   151	        Self::default()
   152	    }
   153	
   154	    /// Test-only failure injection simulating a Keychain failure.
   155	    pub fn set_unavailable(&self, unavailable: bool) {
   156	        self.inner
   157	            .lock()
   158	            .expect("memory secrets poisoned")
   159	            .unavailable = unavailable;
   160	    }
   161	}
   162	
   163	impl Secrets for MemorySecrets {
   164	    fn load(&self) -> Result<Option<TokenBundle>, MailError> {
   165	        let state = self
   166	            .inner
   167	            .lock()
   168	            .map_err(|_| MailError::SecretsUnavailable)?;
   169	        if state.unavailable {
   170	            return Err(MailError::SecretsUnavailable);
   171	        }
   172	        match &state.bundle {
   173	            None => Ok(None),
   174	            Some(json) => Some(
   175	                serde_json::from_str::<TokenBundle>(json)
   176	                    .map_err(|_| MailError::SecretsUnavailable),
   177	            )
   178	            .transpose(),
   179	        }
   180	    }
   181	
   182	    fn store(&self, bundle: &TokenBundle) -> Result<(), MailError> {
   183	        let mut state = self
   184	            .inner
   185	            .lock()
   186	            .map_err(|_| MailError::SecretsUnavailable)?;
   187	        if state.unavailable {
   188	            return Err(MailError::SecretsUnavailable);
   189	        }
   190	        let json = serde_json::to_string(bundle).map_err(|_| MailError::SecretsUnavailable)?;
   191	        state.bundle = Some(json);
   192	        Ok(())
   193	    }
   194	
   195	    fn clear(&self) -> Result<(), MailError> {
   196	        let mut state = self
   197	            .inner
   198	            .lock()
   199	            .map_err(|_| MailError::SecretsUnavailable)?;
   200	        if state.unavailable {
   201	            return Err(MailError::SecretsUnavailable);
   202	        }
   203	        state.bundle = None;
   204	        Ok(())
   205	    }
   206	}
