169	/// Random PKCE verifier (64 base64url chars), its S256 challenge, and a
170	/// random state token.
171	pub(crate) struct Pkce {
172	    verifier: String,
173	    challenge: String,
174	    state: String,
175	}
176	
177	fn generate_pkce() -> Pkce {
178	    let verifier = random_b64url(64);
179	    let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD
180	        .encode(Sha256::digest(verifier.as_bytes()));
181	    let state = random_b64url(32);
182	    Pkce {
183	        verifier,
184	        challenge,
185	        state,
186	    }
187	}
