189	/// Starts the OAuth browser flow: bind a loopback listener on an ephemeral
190	/// port, construct the Google authorization URL (never logged), open it
191	/// externally, and wait for the one-shot callback.
192	pub(crate) fn authorize(
193	    config: &GoogleConfig,
194	    endpoints: &Endpoints,
195	    opener: &UrlOpener,
196	    scope: &str,
197	    cancel: &CancelToken,
198	    timeout: Duration,
199	) -> Result<AuthCode, MailError> {
200	    let pkce = generate_pkce();
201	    let listener = TcpListener::bind("127.0.0.1:0").map_err(|_| MailError::NetworkUnavailable)?;
202	    listener
203	        .set_nonblocking(true)
204	        .map_err(|_| MailError::NetworkUnavailable)?;
205	    let port = listener
206	        .local_addr()
207	        .map_err(|_| MailError::NetworkUnavailable)?
208	        .port();
209	    let redirect_uri = format!("http://127.0.0.1:{port}{CALLBACK_PATH}");
210	    let mut url = Url::parse(&endpoints.authorize).map_err(|_| MailError::ProviderUnavailable)?;
211	    {
212	        let mut query = url.query_pairs_mut();
213	        query.append_pair("client_id", &config.client_id);
214	        query.append_pair("redirect_uri", &redirect_uri);
215	        query.append_pair("response_type", "code");
216	        query.append_pair("scope", scope);
217	        query.append_pair("access_type", "offline");
218	        query.append_pair("prompt", "consent");
219	        query.append_pair("code_challenge", &pkce.challenge);
220	        query.append_pair("code_challenge_method", "S256");
221	        query.append_pair("state", &pkce.state);
222	    }
223	    // The URL carries PKCE/state only; it is handed to the opener, never logged.
224	    opener(url.as_ref())?;
225	    wait_for_code(
226	        &listener,
227	        &redirect_uri,
228	        &pkce.verifier,
229	        &pkce.state,
230	        timeout,
231	        cancel,
232	    )
233	}
