235	/// Accepts loopback connections until the exact callback path arrives with
236	/// the exact state, replies one-shot, and returns the code. Wrong paths,
237	/// wrong states, and OAuth `error` responses are rejected; cancellation and
238	/// the timeout end the wait.
239	fn wait_for_code(
240	    listener: &TcpListener,
241	    redirect_uri: &str,
242	    verifier: &str,
243	    state: &str,
244	    timeout: Duration,
245	    cancel: &CancelToken,
246	) -> Result<AuthCode, MailError> {
247	    let deadline = Instant::now() + timeout;
248	    loop {
249	        if cancel.is_cancelled() {
250	            return Err(MailError::AuthCancelled);
251	        }
252	        if Instant::now() >= deadline {
253	            return Err(MailError::AuthFailed);
254	        }
255	        match listener.accept() {
256	            Ok((mut stream, _)) => {
257	                stream
258	                    .set_read_timeout(Some(POLL_INTERVAL))
259	                    .map_err(|_| MailError::NetworkUnavailable)?;
260	                stream
261	                    .set_write_timeout(Some(Duration::from_secs(2)))
262	                    .map_err(|_| MailError::NetworkUnavailable)?;
263	                match read_request(&mut stream, deadline, cancel) {
264	                    Ok(Some(request)) => {
265	                        let target = request.split_whitespace().nth(1).unwrap_or("");
266	                        // Browsers send origin-form ("/path?query"); absolute
267	                        // form is accepted too (proxies, handcrafted GETs).
268	                        let (path, query) = if target.starts_with("http://") {
269	                            match Url::parse(target) {
270	                                Ok(parsed) => (
271	                                    parsed.path().to_string(),
272	                                    parsed.query().unwrap_or("").to_string(),
273	                                ),
274	                                Err(_) => {
275	                                    respond(&mut stream, "403 Forbidden", "Invalid callback path.");
276	                                    continue;
277	                                }
278	                            }
279	                        } else {
280	                            match target.split_once('?') {
281	                                Some((path, query)) => (path.to_string(), query.to_string()),
282	                                None => (target.to_string(), String::new()),
283	                            }
284	                        };
285	                        let params: HashMap<String, String> =
286	                            form_urlencoded::parse(query.as_bytes())
287	                                .map(|(k, v)| (k.into_owned(), v.into_owned()))
288	                                .collect();
289	                        if path != CALLBACK_PATH {
290	                            respond(&mut stream, "403 Forbidden", "Invalid callback path.");
291	                            continue;
292	                        }
293	                        if params.get("state").map(String::as_str) != Some(state) {
294	                            respond(&mut stream, "403 Forbidden", "Invalid callback.");
295	                            continue;
296	                        }
297	                        if let Some(_oauth_error) = params.get("error").filter(|e| !e.is_empty()) {
298	                            respond(&mut stream, "400 Bad Request", "Authorization failed.");
299	                            return Err(MailError::AuthFailed);
300	                        }
301	                        match params.get("code").map(String::as_str) {
302	                            Some(code) if !code.is_empty() => {
303	                                respond(
304	                                    &mut stream,
305	                                    "200 OK",
306	                                    "Authorization complete. You can close this window.",
307	                                );
308	                                return Ok(AuthCode {
309	                                    code: code.to_string(),
310	                                    redirect_uri: redirect_uri.to_string(),
311	                                    verifier: verifier.to_string(),
312	                                });
313	                            }
314	                            _ => {
315	                                respond(&mut stream, "403 Forbidden", "Invalid callback.");
316	                            }
317	                        }
318	                    }
319	                    Ok(None) => {
320	                        respond(&mut stream, "400 Bad Request", "Invalid callback request.");
321	                    }
322	                    Err(error) => return Err(error),
323	                }
324	            }
325	            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
326	                std::thread::sleep(POLL_INTERVAL);
327	            }
328	            Err(_) => return Err(MailError::NetworkUnavailable),
329	        }
330	    }
331	}
