370	/// Writes the one-shot callback response.
371	fn respond(stream: &mut std::net::TcpStream, status: &str, text: &str) {
372	    let body = format!("<!doctype html><html><body><p>{text}</p></body></html>");
373	    let _ = write!(
374	        stream,
375	        "HTTP/1.1 {status}\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
376	        body.len()
377	    );
378	    let _ = stream.flush();
379	}
