     7	/// Posts the token request to the fixed token endpoint and normalizes the
     8	/// JSON response. Form bodies are buffered in memory (small); no redirects
     9	/// are followed (the HTTP client disables them).
    10	fn token_request(
    11	    endpoints: &Endpoints,
    12	    http: &Client,
    13	    form: Vec<(String, String)>,
    14	    cancel: &CancelToken,
    15	) -> Result<TokenResponse, MailError> {
    16	    if cancel.is_cancelled() {
    17	        return Err(MailError::AuthCancelled);
    18	    }
    19	    let response = http
    20	        .post(&endpoints.token)
    21	        .form(&form)
    22	        .send()
    23	        .map_err(map_http_error)?;
    24	    let status = response.status();
    25	    if status.as_u16() == 400 || status.as_u16() == 401 {
    26	        // Definite credential rejection (invalid_grant, invalid_client...).
    27	        return Err(MailError::AuthFailed);
    28	    }
    29	    if !status.is_success() {
    30	        return Err(MailError::ProviderUnavailable);
    31	    }
    32	    let bytes = read_bounded(response)?;
    33	    let json: serde_json::Value =
    34	        serde_json::from_slice(&bytes).map_err(|_| MailError::InvalidProviderResponse)?;
    35	    let access_token = json
    36	        .get("access_token")
    37	        .and_then(serde_json::Value::as_str)
    38	        .filter(|s| !s.is_empty())
    39	        .ok_or(MailError::InvalidProviderResponse)?
    40	        .to_string();
    41	    let expires_in = json
    42	        .get("expires_in")
    43	        .and_then(serde_json::Value::as_i64)
    44	        .ok_or(MailError::InvalidProviderResponse)?;
    45	    let refresh_token = json
    46	        .get("refresh_token")
    47	        .and_then(serde_json::Value::as_str)
    48	        .filter(|s| !s.is_empty())
    49	        .map(ToOwned::to_owned);
